package dev.zomboidmelee.boxing;
import java.util.*;import net.minecraft.client.Minecraft;import net.minecraft.world.phys.Vec3;import net.minecraft.core.BlockPos;import net.minecraft.world.level.ClipContext;
public class StableLaserChecks33{
 static int n;static void ok(boolean b,String m){n++;if(!b)throw new AssertionError(m);}static void near(double a,double b,String m){ok(Math.abs(a-b)<1e-5,m);}
 public static class BushBlock{}public static class LeavesBlock{}public static class StoneBlock{}public static class Plant extends ParkourChecks25.Block{Object kind;boolean replace;Plant(Object kind,boolean r){super(true);this.kind=kind;replace=r;}public boolean canBeReplaced(){return replace;}public Object getBlock(){return kind;}}
 public static class Hit extends LaserChecks32.Hit{BlockPos pos;Hit(Vec3 v,BlockPos p){super(v);pos=p;}public BlockPos getBlockPos(){return pos;}}
 public static class World extends ParkourChecks25.World{int clips;World(){blocks.put(new BlockPos(0,0,3),new Plant(new BushBlock(),false));blocks.put(new BlockPos(0,0,1),new Plant(new StoneBlock(),false));}public Hit clip(ClipContext c){clips++;for(int z:new int[]{3,1}){double plane=z+1;if(c.from().z>=plane&&c.to().z<plane){double a=(plane-c.from().z)/(c.to().z-c.from().z);return new Hit(new Vec3(c.from().x+(c.to().x-c.from().x)*a,c.from().y+(c.to().y-c.from().y)*a,plane),new BlockPos(0,0,z));}}return new Hit(null,null);}}
 public static void main(String[] args){var w=new World();var p=new LaserChecks32.Local();var end=Laser32.clip(p,w,new double[]{.5,.5,6},new double[]{.5,.5,0});near(end[2],2.003,"berry bush is traversed and solid wall behind still stops beam");ok(w.clips==2,"one traversal per plant cell, no recursion or tiny-step loop");ok(Laser32.foliage(new Plant(new BushBlock(),false))&&Laser32.foliage(new Plant(new LeavesBlock(),false))&&Laser32.foliage(new Plant(new StoneBlock(),true)),"bushes, leaves and replaceable grass are transparent");ok(!Laser32.foliage(new Plant(new StoneBlock(),false)),"solid nonplant state remains an obstacle");ok(Lean30.clear(p,w,.5,.5,6,.5,.5,2.5),"vegetation does not cause automatic corner lean");ok(!Lean30.clear(p,w,.5,.5,6,.5,.5,0),"solid cover behind vegetation still blocks corner camera");
 Lean30.heldEdge=1;Lean30.edgeUntil=0;Lean30.candidateEdge=0;for(int i=0;i<100;i++)ok(Lean30.stableEdge(i%2==0?-1:1,0,i*50_000_000L)!=-1,"alternating probes cannot drive endless left-right corner oscillation");Lean30.stableEdge(-1,0,6_000_000_000L);ok(Lean30.stableEdge(-1,0,6_250_000_000L)==-1,"stable opposite cover can still change lean after hysteresis");var mc=Minecraft.INSTANCE;mc.player=p;mc.level=w;mc.screen=null;mc.options.firstPerson=true;p.physics=w;Bodycam26.owner=p;Bodycam26.world=w;Lean30.owner=null;Lean30.tick(mc,p,w);Lean30.target=1;long[]clock={10_000_000_000L};BoxingClient16.CLOCK=()->clock[0];Lean30.sampled=clock[0];for(int i=0;i<80;i++){clock[0]+=16_666_667;Lean30.amount();}var cam=new CornerCarryChecks30.Camera();Lean30.world=new ParkourChecks25.World();Lean30.camera(cam);double x=cam.position.x,y=cam.position.y;for(int i=0;i<600;i++)Lean30.camera(cam);near(cam.position.x,x,"repeated camera tails never accumulate sideways displacement");near(cam.position.y,y,"camera height never drifts during lean");var event=new net.neoforged.neoforge.client.event.ViewportEvent.ComputeCameraAngles();event.setRoll(0);for(int i=0;i<600;i++)Lean30.angles(event);ok(Math.abs(event.getRoll())<=10.001,"repeated lean event remains bounded instead of spinning");
 double[] view=LaserChecks32.transform(.4,0,0,0);Laser32.stage(new LaserChecks32.Stage("minecraft:after_sky",new LaserChecks32.Mat(view)));var root=new LaserChecks32.Stack(LaserChecks32.transform(1.4,10,5,9));Laser32.begin(p,root);Laser32.end();for(int i=0;i<16;i++)near(Laser32.view[i],view[i],"entity transforms cannot poison this frame world camera matrix");
 var bad=new LaserChecks32.Vertices();Laser32.draw(bad,Matrix32.identity(),new double[]{0,0,5},.004,0xFF0000,true,true);ok(bad.points.isEmpty(),"laser behind near plane cannot create full-screen triangles");double[]front=Matrix32.identity();front[14]=-.4;var crossing=new LaserChecks32.Vertices();Laser32.draw(crossing,front,new double[]{0,0,4},.004,0x00FF00,true,true);ok(crossing.points.size()==16,"beam crossing camera plane is clipped and has no huge endpoint quad");for(var v:crossing.points)ok(v[2]<=-.079999,"all emitted vertices stay in front of near plane");
 for(int i=0;i<90;i++){double[]m=LaserChecks32.transform(i*.05,.2,-.1,-.3),origin=Matrix32.point(m,0,0,0),tip=Matrix32.point(m,0,0,-1),ray=Laser32.barrel(origin,origin,tip);double dx=ray[0]-origin[0],dy=ray[1]-origin[1],dz=ray[2]-origin[2];near(Math.sqrt(dx*dx+dy*dy+dz*dz),256,"running barrel axis stays normalised");near(dx/256,tip[0]-origin[0],"laser follows actual rotating gun attachment");}
 System.out.println("VEGETATION_SOLID_CLIP_STABLE_LEAN_CAMERA_MATRIX_NEAR_PLANE_BARREL_CHECKS="+n);}
}
